#!/usr/bin/env julia
#       $Id$
#  D. Sandwell 1/12/07
#
# alias rm 'rm -f'
# unset noclobber

function main(argv::Vector{String})
    local V::Vector{String}
    if isfile(joinpath(homedir(), ".quiet"))
        V = String[]
    else
        V = ["-V"]
    end

    #
    #
    #  project an ASCII file from range/azimuth coordinates into lon/lat coordinates
    #  this version only works with GMT V4.0 and higher
    #
    #  Input:
    #  trans.dat    - file generated by llt_grid2rat  (r a topo lon lat)
    #  phase_ra.txt - an ASCII file of phase or anything
    #
    #  Output:
    #  phase_ll.txt - an ASCII file of phase in longitude/latitude coordinates
    #
    # check for number of arguments
    #
    if length(argv) < 3
        println(" ")
        println("Usage: proj_ra2ll_ascii.csh trans.dat phase.txt phase_ll.txt")
        println("        trans.dat    - file generated by SAT_llt2rat  (r a topo lon lat)")
        println("        phase_ra.txt - an ASCII file of phase or anything")
        println("        phase_ll.txt - output file in lon/lat-coordinates")
        println(" ")
        exit(1)
    end
    #
    #   make grids of longitude and latitude versus range and azimuth unless they already exist
    #
    if !isfile("raln.grd") || !isfile("ralt.grd")
        run(pipeline(`gmt gmtconvert $(argv[1]) -o0,1,3 -bi5d -bo3f`, stdout="raln"))
        run(pipeline(`gmt gmtconvert $(argv[1]) -o0,1,4 -bi5d -bo3f`, stdout="ralt"))
        # awk '{ if ($4 > 180.) printf("%f %f %e \n",$1,$2,$4-360.); else printf("%f %f %e \n",$1,$2,$4) }' < $1 | gmtconvert -bos3 > raln
        # awk '{ printf("%f %f %e \n",$1,$2,$5) }' < $1 | gmtconvert -bos3 > ralt
        #
        ginfo = strip(read(`gmt gmtinfo $(argv[2]) -I16/32`, String))
        run(`gmt surface raln $ginfo -bi3f -I8/32 -T.50 -Graln.grd $V`)
        ginfo2 = strip(read(`gmt gmtinfo $(argv[2]) -I16/32`, String))
        run(`gmt surface ralt $ginfo2 -bi3f -I8/32 -T.50 -Gralt.grd $V`)
    end

    #
    # get the lon, lat, phase columns and grid
    #
    run(pipeline(`gmt grdtrack $(argv[2]) -nl -Graln.grd -Gralt.grd -o3,4,2`, stdout=argv[3]))

    #
    # clean
    #
    for f in readdir(".")
        if startswith(f, "rap")
            rm(f; force=true)
        end
    end
    rm("llp"; force=true)
    rm("llpb"; force=true)
end

main(ARGS)
